action.code:
if (!root) {
    root = new TreeNode;
    root->value = item;
    root->left = nullptr;
    root->right = nullptr;
    root->bFactor = 0;
} else {
    if (item < root->value) {
        avlInsert(root->left, item);
    } else {
        avlInsert(root->right, item);
    }
    root->bFactor = _getBalance(root);
    if (root->bFactor > 1) {
        if (root->left->bFactor > 0) {
            _rotateRight(root);
        } else {
            _rotateLeft(root->left);
            _rotateRight(root);
        }
        _updatebFactors(root);
    } else if (root->bFactor < -1) {
        if (root->right->bFactor < 0) {
            _rotateLeft(root);
        } else {
            _rotateRight(root->right);
            _rotateLeft(root);
        }
        _updatebFactors(root);
    }
}

